sys_script.script:
(function executeRule(current, previous) {

    // Map each Task Type value to its group's exact name
    var groupMap = {
        'Documentation': 'Documentation Team',
        'Billing': 'Billing Team',
        'TPA Insurance': 'Insurance Team',
        'Pharmacy': 'Pharmacy Team',
        'Transportation': 'Transport Team',
        'Follow-up': 'Documentation Team' // no dedicated group exists yet — change this if you create one
    };

    var taskType = current.task_type.toString();
    var groupName = groupMap[taskType];

    if (!groupName) {
        gs.addErrorMessage('Unrecognized Task Type "' + taskType + '" — check the groupMap keys match your choice list values exactly.');
        return;
    }

    var grp = new GlideRecord('x_snc_discharge_0_departments');
    grp.addQuery('name', groupName);
    grp.query();

    if (grp.next()) {
        current.assigned_group = grp.sys_id;
    } else {
        gs.addErrorMessage('Group "' + groupName + '" not found — check it was created with this exact name.');
    }

})(current, previous);
